<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import tokenUtil from 'src/utils/tokenUtil';
import { VueRecaptcha } from 'vue-recaptcha';
import { isMobile } from 'src/supplier/utils';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import { ApiExceptions } from 'src/exceptions';
import { supplierApiService } from 'src/services';
import { AppVersion } from 'src/utils/app_version';
import helperMixin from 'src/mixins/helperMixin.js';
import { LocalStorage, SessionStorage } from 'quasar';
import { dynamicObj } from 'src/pages/asn_shipment/store';
import { DOC2API_URL, SUPPORT_URL } from 'src/pages/APIs';
import {
  setApiRegion,
  setAuthRegion,
  getCurrentApiRegion,
  isRegionalStage,
} from 'src/pages/api-base-url';
import { userApiService } from 'src/services';
import { authSdkService } from 'src/services/user/authSdkService';
import { specialChars, passwordPattern, CONSTANTS } from 'src/constants';
import LanguageDropdown from 'src/components/LayoutHeader/LanguageDropdown.vue';
import { notify } from 'src/components/notifications/notify';
import {
  useAuthTokenStore,
  useDocLockStore,
  useUserStore,
} from 'src/store/main';

interface MagicLinkData {
  [key: string | number]: any;
}

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, tokenUtil],
  components: {
    LanguageDropdown,
    VueRecaptcha,
    Loader,
  },
  data() {
    return {
      lastName: '',
      firstName: '',
      email: '',
      password: '',
      confirmPassword: '',
      agree: false,
      users: ref([]),
      emailError: '',
      passwordError: '',
      confpasswordError: '',
      agreeError: '',
      recaptchaKeyError: '',
      lastNameError: '',
      firstNameError: '',
      userDialog: ref(false),
      showPassword: false,
      showConfPassword: false,
      captchaResponse: ref(''),
      magicLinkData: {} as dynamicObj,
      setEmailDisable: false,
    };
  },
  setup() {
    const doc_lock_store = useDocLockStore();
    const { getUniqueLockId } = doc_lock_store;

    const auth_token_store = useAuthTokenStore();
    const { setAuthToken } = auth_token_store;
    const { getPublicLogo } = supplierApiService;

    const user_store = useUserStore();
    const { fetchUserSettings } = user_store;

    const logo = ref('/images/fellowpro-logo.png');
    const useDynamicLayout = false;
    return {
      isMobile,
      setAuthToken,
      getPublicLogo,
      getUniqueLockId,
      fetchUserSettings,
      logo,
      useDynamicLayout,
      recaptcha_key: ref(''),
      processing: ref(false),
    };
  },
  computed: {
    buttonLabel() {
      return this.showPassword ? 'Hide' : 'Show';
    },
  },
  async mounted() {
    LocalStorage.remove('user_details');
    this.setRecaptchaKey();
    // get_magic_link_data is a pure JWT decode (region-agnostic), so this
    // succeeds on the default region and returns the supplier's region inside
    // the payload.
    await this.getMagicLinkToken();
    // Switch the SPA to the supplier's region BEFORE any region-specific call
    // (layout preference, register, ...). If a switch is needed this reloads,
    // so stop here — the flow restarts on the correct host after reload.
    if (this.applyMagicLinkRegion()) {
      return;
    }
    await this.getSupplierLayoutPreference();
    const result = await this.getPublicLogo(this.magicLinkData.org_id);
    if (result.data.success) {
      const logoObject = JSON.parse(result.data.data);

      if (!logoObject) {
        return;
      }
      if (this.isMobile()) {
        this.logo = logoObject.mobile.logo;
      } else {
        this.logo = logoObject.desktop.logo;
      }
    }
  },
  methods: {
    languageChanged() {
      LocalStorage.set(CONSTANTS.selected_language, this.locale);
      SessionStorage.set('event_name', 'language_change');
      LocalStorage.remove('doc_types');
    },
    setRecaptchaKey() {
      if (!process.env.APP_VUE_RECAPTCHA_KEY) {
        logInfo('Recaptcha key is missing');
        return;
      }
      this.recaptcha_key = process.env.APP_VUE_RECAPTCHA_KEY;
    },
    enterS() {
      this.supplierRegister();
    },
    captcaResp(captResponse: any) {
      this.captchaResponse = captResponse;
    },
    resetRecaptcha() {
      try {
        (<any>this).$refs['recaptcha'].reset();
      } catch (err: any) {
        logError(err);
      }
    },
    toggleShow() {
      this.showPassword = !this.showPassword;
    },
    toggleShowConf() {
      this.showConfPassword = !this.showConfPassword;
    },
    goCloud() {
      window.open('https://polydocs.io/');
    },
    user_login() {
      this.$router.push('/');
    },
    // Magic-link region handoff. The supplier's region is encoded in the JWT
    // payload (the referrer org's region) and returned by get_magic_link_data,
    // which is a region-agnostic decode. Once we have it, persist the region
    // and reload so DOC2API_URL/AUTH_URL rebuild with the correct prefix before
    // any region-specific call. Returns true when a reload is triggered (caller
    // stops). No-op when there's no region or it already matches — the equality
    // check prevents a reload loop (after reload the persisted region matches).
    applyMagicLinkRegion(): boolean {
      if (!isRegionalStage()) {
        return false;
      }
      const dataRegion = (this.magicLinkData as { region?: string })?.region;
      if (!dataRegion) {
        return false;
      }
      const region = dataRegion === 'us' ? 'us' : 'eu';
      if (region === getCurrentApiRegion()) {
        return false;
      }
      setAuthRegion(region);
      setApiRegion(region);
      window.location.reload();
      return true;
    },
    async getMagicLinkToken() {
      const token = this.$route.query.token as string;
      if (!token) {
        return (this.setEmailDisable = false);
      }

      await axios
        .post(`${DOC2API_URL}/supplier/get_magic_link_data?token=${token}`)
        .then((result: any) => {
          this.magicLinkData = result.data;
          this.setEmailDisable = true;
          this.password = '';
          this.email = (
            this.magicLinkData as { responder_email: string }
          ).responder_email;
          this.firstName = (
            this.magicLinkData as { responder_first_name: string }
          ).responder_first_name;
          this.lastName = (
            this.magicLinkData as { responder_name: string }
          ).responder_name;
        })
        .catch((err: any) => {
          const msg = ApiExceptions.getErrorMessage(err);
          notify.error(msg);
        });
    },
    async getSupplierLayoutPreference() {
      try {
        const org_id = (this.magicLinkData as { supplier_as_org_id: string })
          .supplier_as_org_id;
        const res = await axios.get(
          `${DOC2API_URL}/supplier/get_supplier_layout_preference?org_id=${org_id}`,
        );
        if (res.data.success) {
          this.useDynamicLayout = res.data.data;
        }
      } catch (error) {
        logError(error);
      }
    },
    isValidPassword(password: any) {
      return passwordPattern.test(password);
    },
    validateForm() {
      let error = false;
      this.passwordError = '';
      this.confpasswordError = '';
      this.lastNameError = '';
      this.firstNameError = '';
      this.agreeError = '';
      this.emailError = '';
      this.recaptchaKeyError = '';

      if (this.firstName === '') {
        this.firstNameError = 'First name is required';
        error = true;
      }
      if (this.lastName === '') {
        this.lastNameError = 'Last name is required';
        error = true;
      }
      if (this.email === '') {
        this.emailError = 'Email is required';
        error = true;
      }
      if (!this.validateEmail(this.email)) {
        this.emailError = 'Please enter valid email';
        error = true;
      }
      if (this.password === '') {
        this.passwordError = 'Password is required';
        error = true;
      }
      if (this.confirmPassword === '') {
        this.confpasswordError = 'Confirm password is required';
        error = true;
      }
      if (this.password && !this.isValidPassword(this.password)) {
        this.passwordError =
          'Passwords must be 6-20 characters long and include at least 1 number, 1 uppercase letter, and 1 special character';
        error = true;
      }
      if (this.confirmPassword && !this.isValidPassword(this.confirmPassword)) {
        this.confpasswordError =
          'Passwords must be 6-20 characters long and include at least 1 number, 1 uppercase letter, and 1 special character';
        error = true;
      }
      if (
        this.password &&
        this.confirmPassword &&
        this.isValidPassword(this.confirmPassword) &&
        this.password !== this.confirmPassword
      ) {
        this.confpasswordError = 'Passwords do not match';
        error = true;
      }
      if (this.agree === false) {
        this.agreeError = 'Please agree to the Terms and Conditions';
        error = true;
      }
      if (!this.captchaResponse) {
        this.recaptchaKeyError = 'Please click if you are not a robot';
        error = true;
      }
      return error;
    },
    async afterLoginEvent(tokenInfo: any) {
      try {
        this.processing = true;
        this.setTokenInLocalStorage(tokenInfo);
        await this.setAuthToken(tokenInfo.access_token);
        await authSdkService.setUserSession(tokenInfo.user_id);
        this.getUniqueLockId();
        AppVersion.updateVersion();
        await this.fetchUserSettings();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    goViewTermCondition() {
      const org_id = (this.magicLinkData as { org_id: string }).org_id;
      if (org_id) {
        const url = this.$router.resolve(
          `/supplier/register/terms_and_conditions/${org_id}`,
        );
        window.open(url.href, '_blank');
      }
    },
    async supplierRegister() {
      try {
        let hasError = this.validateForm();
        if (!hasError) {
          this.processing = true;
          const formData = new FormData();

          formData.append(
            'org_id',
            (this.magicLinkData as MagicLinkData).org_id,
          );
          formData.append(
            'supplier_as_org_id',
            (this.magicLinkData as MagicLinkData).supplier_as_org_id,
          );
          formData.append('first_name', this.firstName);
          formData.append('last_name', this.lastName);
          formData.append('email', this.email);
          formData.append('password', this.password);
          formData.append('is_admin', 'true');
          formData.append(
            'referrer_user_id',
            (this.magicLinkData as MagicLinkData).referrer_user_id,
          );

          const res = await axios.post(
            `${DOC2API_URL}/supplier/register`,
            formData,
          );
          if (res.data.success === false) {
            notify.error(res.data.message);
          } else {
            const data = {
              username: this.email,
              password: this.password,
            };
            const response = await userApiService.login(data);
            if (response) {
              await this.afterLoginEvent(response);
              const recordId = res.data.supplier_lookup_record_id as
                | string
                | null;
              const orgId = res.data.supplier_as_org_id as string;
              this.$router.push(
                `/supplier/register-wizard/${recordId ?? 'supplier_lookup_record_id'}/${orgId}`,
              );
            }
          }
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.processing = false;
        this.resetRecaptcha();
      }
    },
  },
});
</script>

